import { animate, style, transition, trigger } from '@angular/animations';
import { CommonModule } from '@angular/common';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Component, computed, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Customer, EventRecord, Role } from './models';
import { approvals as demoApprovals, customers as demoCustomers, events as demoEvents } from './demo-data';
import { environment } from '../environments/environment';

type Page = 'dashboard' | 'customers' | 'customer' | 'entitlements' | 'approvals' | 'audit' | 'events' | 'health';
interface AuthResponse { accessToken: string; tokenType: string; role: Role; displayName: string; }
interface CustomerResponse { id: string; customerNumber: string; legalName: string; industry: string; riskLevel: string; onboardingStage: string; updatedAt: string; }
interface EntitlementResponse { id: string; customerId: string; product: string; permission: string; requestedBy: string; requestedAt: string; status: string; riskLevel: string; correlationId: string; }
interface AuditResponse { actor: string; actorRole: string; action: string; entityType: string; entityId: string; correlationId: string; occurredAt: string; }
interface EventResponse { eventId: string; eventType: string; entityId: string; correlationId: string; status: string; processedAt: string; }
interface DemoUser { email: string; password: string; displayName: string; role: Role; }

@Component({
  selector: 'nx-root', standalone: true, imports: [CommonModule, FormsModule],
  animations: [trigger('content', [transition('* => *', [style({opacity: 0, transform: 'translateY(8px)'}), animate('220ms cubic-bezier(.4,0,.2,1)', style({opacity: 1, transform: 'none'}))])])],
  template: `
    @if (!signedIn()) {
      <main class="login-shell">
        <section class="login-brand">
          <div class="brand"><span class="brand-mark">N</span><span>NEXORA</span></div>
          <div class="brand-copy"><p class="eyebrow">COMMERCIAL BANKING OPERATIONS</p><h1>Secure operations.<br>Confident decisions.</h1><p>One control plane for customer onboarding, entitlements, and oversight.</p></div>
          <div class="network" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><b></b><b></b><b></b></div>
          <div class="people-video" aria-hidden="true"><span class="field"></span><span class="laugh laugh-one">ha</span><span class="laugh laugh-two">ha</span><span class="person person-one"><i></i><em></em><strong></strong></span><span class="person person-two"><i></i><em></em><strong></strong></span><span class="person person-three"><i></i><em></em><strong></strong></span></div>
          <small>Protected by Nexora Secure Access</small>
        </section>
        <section class="login-form"><div class="login-card" [class.registering]="isRegistering()"><p class="eyebrow">{{isRegistering() ? 'CREATE SECURE ACCESS' : 'SECURE SIGN IN'}}</p><h2>{{isRegistering() ? 'Create your account' : 'Welcome back'}}</h2><p class="muted">{{isRegistering() ? 'Set up your secure Nexora workspace credentials.' : 'Use your Nexora credentials to continue.'}}</p>
          @if (isRegistering()) { <label>Full name<input [(ngModel)]="fullName" type="text" placeholder="Alex Morgan"></label> }
          <label>Email or employee ID<input [(ngModel)]="email" type="email" placeholder="name@nexora.demo"></label>
          <label>Password<span class="password-field"><input [(ngModel)]="password" [type]="showPassword() ? 'text' : 'password'" placeholder="{{isRegistering() ? 'Create a strong password' : 'Enter your password'}}"><button type="button" class="password-toggle" (click)="showPassword.set(!showPassword())" [attr.aria-label]="showPassword() ? 'Hide password' : 'Show password'"><span class="material-icons-round">{{showPassword() ? 'visibility_off' : 'visibility'}}</span></button></span></label>
          @if (isRegistering()) { <label>Confirm password<span class="password-field"><input [(ngModel)]="confirmPassword" [type]="showConfirmPassword() ? 'text' : 'password'" placeholder="Re-enter your password"><button type="button" class="password-toggle" (click)="showConfirmPassword.set(!showConfirmPassword())" [attr.aria-label]="showConfirmPassword() ? 'Hide password' : 'Show password'"><span class="material-icons-round">{{showConfirmPassword() ? 'visibility_off' : 'visibility'}}</span></button></span></label>
            <div class="password-rules" aria-live="polite"><p>Password requirements</p><span [class.met]="passwordRules().length"><i class="material-icons-round">{{passwordRules().length ? 'check_circle' : 'radio_button_unchecked'}}</i> At least 12 characters</span><span [class.met]="passwordRules().upper"><i class="material-icons-round">{{passwordRules().upper ? 'check_circle' : 'radio_button_unchecked'}}</i> Uppercase and lowercase letter</span><span [class.met]="passwordRules().number"><i class="material-icons-round">{{passwordRules().number ? 'check_circle' : 'radio_button_unchecked'}}</i> One number and one special character</span></div>
            @if (confirmPassword && !passwordsMatch()) { <p class="form-error"><span class="material-icons-round">error_outline</span> Passwords do not match.</p> }
          }
          @if (!isRegistering()) { <div class="login-row"><label class="check"><input type="checkbox" checked> Remember me</label><a>Forgot password?</a></div> }
          @if (authError) { <p class="form-error"><span class="material-icons-round">error_outline</span>{{authError}}</p> }
          <button class="primary wide" [disabled]="authPending() || (isRegistering() && !canRegister())" (click)="isRegistering() ? register() : login()">{{authPending() ? 'Securing access...' : isRegistering() ? 'Create secure account' : 'Sign in'}} <span class="material-icons-round">arrow_forward</span></button>@if (!isRegistering()) { <button class="secondary wide" (click)="showInfo('Single sign-on needs your organization identity provider configuration.')">Sign in with SSO</button> }
          <p class="account-switch">{{isRegistering() ? 'Already have access?' : 'New to Nexora?'}} <button type="button" (click)="switchAccessMode()">{{isRegistering() ? 'Sign in' : 'Create an account'}}</button></p>
          <p class="security"><span class="material-icons-round">verified_user</span> Authorized personnel only. Activity may be monitored and audited.</p>
        </div></section>
      </main>
    } @else {
      <div class="app-shell" [class.collapsed]="collapsed()">
        <aside class="sidebar"><div class="sidebar-head"><div class="brand"><span class="brand-mark">N</span><span class="brand-name">NEXORA</span></div><button class="icon-button collapse" (click)="collapsed.set(!collapsed())"><span class="material-icons-round">{{collapsed() ? 'menu' : 'keyboard_double_arrow_left'}}</span></button></div>
          <p class="sidebar-caption">COMMERCIAL OPERATIONS</p>
          <nav>
            <button [class.active]="page()==='dashboard'" (click)="go('dashboard')"><span class="material-icons-round">grid_view</span><span>Dashboard</span></button>
            <button [class.active]="page()==='customers' || page()==='customer'" (click)="go('customers')"><span class="material-icons-round">apartment</span><span>Customers</span></button>
            @if (canOnboard()) { <button (click)="go('customers')"><span class="material-icons-round">account_tree</span><span>Onboarding</span></button> }
            @if (canManageEntitlements()) { <button [class.active]="page()==='entitlements'" (click)="go('entitlements')"><span class="material-icons-round">key</span><span>Entitlements</span></button> }
            @if (canApprove()) { <button [class.active]="page()==='approvals'" (click)="go('approvals')"><span class="material-icons-round">task_alt</span><span>Approvals <em>{{approvals().length}}</em></span></button> }
            <button [class.active]="page()==='audit'" (click)="go('audit')"><span class="material-icons-round">history</span><span>Audit History</span></button>
            <p class="nav-label">OPERATIONS</p>
            @if (isAdmin()) { <button [class.active]="page()==='events'" (click)="go('events')"><span class="material-icons-round">hub</span><span>Event Monitor</span></button><button [class.active]="page()==='health'" (click)="go('health')"><span class="material-icons-round">monitor_heart</span><span>System Health</span></button> }
          </nav>
          <div class="profile"><div class="avatar">{{initials()}}</div><div class="profile-copy"><strong>{{currentUser().displayName}}</strong><span>{{roleLabel()}}</span></div><button class="icon-button" (click)="signOut()"><span class="material-icons-round">logout</span></button></div>
        </aside>
        <main class="workspace"><header class="topbar"><div class="crumb"><span>Commercial Operations</span><b>/</b><strong>{{pageTitle()}}</strong></div><div class="top-actions"><button class="search" (click)="openSearch()"><span class="material-icons-round">search</span><span>Search customers, accounts, requests...</span><kbd>Ctrl K</kbd></button><span class="env">UAT</span><button class="icon-button" (click)="showInfo('Help center: choose Customers to search relationships, or use your role-specific operations menu.')" aria-label="Open help"><span class="material-icons-round">help_outline</span></button><button class="icon-button notification" (click)="showInfo('No new high-priority notifications. Your activity is recorded in Audit History.')" aria-label="View notifications"><span class="material-icons-round">notifications_none</span><i></i></button></div></header>
          <div class="page-content" [@content]="page()">
            @switch (page()) {
              @case ('dashboard') { <ng-container *ngTemplateOutlet="dashboard"></ng-container> }
              @case ('customers') { <ng-container *ngTemplateOutlet="customerList"></ng-container> }
              @case ('customer') { <ng-container *ngTemplateOutlet="customer360"></ng-container> }
              @case ('entitlements') { <ng-container *ngTemplateOutlet="entitlementPage"></ng-container> }
              @case ('approvals') { <ng-container *ngTemplateOutlet="approvalPage"></ng-container> }
              @case ('audit') { <ng-container *ngTemplateOutlet="auditPage"></ng-container> }
              @case ('events') { <ng-container *ngTemplateOutlet="eventPage"></ng-container> }
              @case ('health') { <ng-container *ngTemplateOutlet="healthPage"></ng-container> }
            }
          </div>
        </main>
      </div>
      @if (drawer()) { <div class="scrim" (click)="drawer.set('')"></div><aside class="drawer"><button class="icon-button close" (click)="drawer.set('')"><span class="material-icons-round">close</span></button>
        @if (drawer()==='request') { <p class="eyebrow">ENTITLEMENT REQUEST</p><h2>Request access</h2><div class="steps"><span class="active">1</span><span [class.active]="requestStep()>1">2</span><span [class.active]="requestStep()>2">3</span><span [class.active]="requestStep()>3">4</span></div>
          @if(requestStep()===1){<h3>Select product</h3><button class="select-card active" (click)="selectedProduct.set('Wire Transfers')"><span class="material-icons-round">account_balance</span><span><b>Wire Transfers</b><small>High risk payment capability</small></span><span class="material-icons-round">check_circle</span></button>}
          @if(requestStep()===2){<h3>Configure permissions</h3><div class="permission-row"><span>View wire activity</span><span class="material-icons-round on">check_circle</span></div><div class="permission-row"><span>Create wire payments</span><span class="material-icons-round on">check_circle</span></div><div class="permission-row high"><span><b>Release wire transfers</b><small>High-risk entitlement - dual approval required</small></span><span class="switch on"></span></div>}
          @if(requestStep()===3){<h3>Business justification</h3><label>Reason for access<textarea [(ngModel)]="justification" placeholder="Describe the operational need and approval controls."></textarea></label><p class="info-note"><span class="material-icons-round">info</span> This request needs two independent approvers.</p>}
          @if(requestStep()===4){<h3>Review changes</h3><div class="comparison"><div><small>BEFORE</small><p>View<br>Create</p></div><div><small>AFTER</small><p>View<br>Create<br><mark>Release</mark></p></div></div><p class="info-note"><span class="material-icons-round">warning_amber</span> High-risk entitlement</p>}
          <div class="drawer-footer"><button class="secondary" (click)="requestStep.set(requestStep()-1)" [disabled]="requestStep()===1">Back</button><button class="primary" (click)="advanceRequest()">{{requestStep()===4?'Submit for approval':'Continue'}}</button></div>
        } @else { <p class="eyebrow">APPROVAL REQUEST</p><h2>{{selectedApproval()?.change || 'Entitlement request'}}</h2><span class="badge critical">{{selectedApproval()?.risk || 'high'}} RISK</span><div class="request-meta"><span>Request ID</span><b>{{selectedApproval()?.id}}</b><span>Customer</span><b>{{selectedApproval()?.customer}}</b><span>Requested by</span><b>{{selectedApproval()?.requestedBy}}</b><span>Submitted</span><b>{{selectedApproval()?.submitted}}</b></div><h3>Requested change</h3><div class="comparison"><div><small>CURRENT STATE</small><p>View<br>Create</p></div><div><small>PROPOSED STATE</small><p>View<br>Create<br><mark>Release</mark></p></div></div><p class="info-note"><span class="material-icons-round">warning_amber</span> Independent maker-checker approval is required.</p><h3>Business justification</h3><p class="muted">This decision is captured in the immutable audit log and published as a domain event.</p><div class="drawer-footer"><button class="secondary" (click)="showInfo('The maker has been notified to amend and resubmit this request.')">Request changes</button><button class="danger" (click)="reject()">Reject</button><button class="primary" (click)="approve()">Approve</button></div> }
      </aside> }
      @if(toast()) { <div class="toast"><span class="material-icons-round">check_circle</span>{{toast()}}<button (click)="toast.set('')">×</button></div> }
    }

    <ng-template #dashboard><section class="page-header"><div><p class="eyebrow">TUESDAY, AUGUST 26</p><h1>Good morning, {{firstName()}}</h1><p class="muted">{{isReadOnly() ? 'You have read-only access to customer and audit information.' : "Here's what needs your attention today."}}</p></div>@if (canOnboard()) { <button class="primary" (click)="createCustomer()"><span class="material-icons-round">add</span> New customer</button> }</section>
      <section class="metrics"><article><span class="metric-icon blue material-icons-round">groups</span><small>Total customers</small><strong>1,248</strong><p class="positive">↑ 8.2% <span>this month</span></p></article><article><span class="metric-icon amber material-icons-round">account_tree</span><small>Onboarding</small><strong>37</strong><p>12 awaiting KYC</p></article><article><span class="metric-icon violet material-icons-round">task_alt</span><small>Pending approvals</small><strong>8</strong><p class="high-text">3 high priority</p></article><article><span class="metric-icon red material-icons-round">error_outline</span><small>Exceptions</small><strong>3</strong><p class="high-text">Requires attention</p></article></section>
      <section class="grid dashboard-grid"><article class="card pipeline"><div class="section-heading"><div><h2>Onboarding pipeline</h2><p>37 active customer journeys</p></div><button class="text-button" (click)="go('customers')">View onboarding queue <span class="material-icons-round">arrow_forward</span></button></div><div class="pipeline-flow">@for(stage of pipeline; track stage.label; let last=$last){<button (click)="filterPipeline(stage.label)" [class.selected]="filterStage()===stage.label"><b>{{stage.count}}</b><span>{{stage.label}}</span></button>@if(!last){<i></i>}}</div><div class="pipeline-bar"><span></span></div><p class="legend"><i class="blue-dot"></i> Entitlements currently has the greatest volume <span>Updated 2 minutes ago</span></p></article>
      <article class="card attention"><div class="section-heading"><div><h2>Needs attention</h2><p>Prioritized operational exceptions</p></div><button class="icon-button" (click)="showInfo('Priority exceptions are listed below. Select an item to review it.')" aria-label="About exceptions"><span class="material-icons-round">more_horiz</span></button></div>@for(item of attention; track item.name){<button class="attention-item" (click)="go(item.name==='ENT-49218'?'events':'customer')"><span class="attention-icon material-icons-round">{{item.icon}}</span><span><b>{{item.name}}</b><small>{{item.detail}}</small></span><em [class]="item.severity">{{item.severity}}</em></button>}</article></section>
      <section class="grid lower-grid"><article class="card activity"><div class="section-heading"><div><h2>Portfolio movement</h2><p>Customer volume across the last 30 days</p></div><span class="select">30 days <span class="material-icons-round">expand_more</span></span></div><div class="chart"><div class="chart-y"><span>1,300</span><span>1,250</span><span>1,200</span><span>1,150</span></div><svg viewBox="0 0 600 190" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1463ff" stop-opacity=".2"/><stop offset="1" stop-color="#1463ff" stop-opacity="0"/></linearGradient></defs><path d="M0,151 C40,130 57,145 94,120 S151,121 188,102 S249,115 280,78 S343,90 375,61 S436,80 468,48 S535,59 600,13 L600,190 L0,190Z" fill="url(#area)"/><path d="M0,151 C40,130 57,145 94,120 S151,121 188,102 S249,115 280,78 S343,90 375,61 S436,80 468,48 S535,59 600,13" fill="none" stroke="#1463ff" stroke-width="3"/></svg></div></article><article class="card coverage"><div class="section-heading"><div><h2>Approval coverage</h2><p>Queue ownership by team</p></div></div><div class="donut"><div><b>8</b><small>open</small></div></div><div class="coverage-list"><p><i></i> Treasury approvals <b>4</b></p><p><i></i> Customer changes <b>3</b></p><p><i></i> KYC decisions <b>1</b></p></div></article></section></ng-template>

    <ng-template #customerList><section class="page-header"><div><p class="eyebrow">CUSTOMER DIRECTORY</p><h1>Customers</h1><p class="muted">{{isReadOnly() ? 'View commercial banking relationships and immutable activity.' : 'Manage commercial banking relationships and onboarding activity.'}}</p></div>@if (canOnboard()) { <button class="primary" (click)="createCustomer()"><span class="material-icons-round">add</span> New customer</button> }</section><section class="card table-card"><div class="table-tools"><label class="table-search"><span class="material-icons-round">search</span><input [(ngModel)]="customerSearch" placeholder="Search customers or IDs"></label><button class="secondary" (click)="showInfo('Use the search field to filter customer names or IDs.')"><span class="material-icons-round">tune</span> Filters</button><button class="secondary" (click)="showInfo('Saved views are organization-specific and can be configured after deployment.')">Saved views <span class="material-icons-round">expand_more</span></button><span class="push"></span><button class="secondary" (click)="showInfo('Customer export is restricted to the reporting service in this demo.')"><span class="material-icons-round">download</span> Export</button><button class="icon-button" (click)="showInfo('All customer columns are currently visible.')" aria-label="Configure columns"><span class="material-icons-round">view_column</span></button></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox"></th><th>Customer</th><th>Customer ID</th><th>Industry</th><th>Relationship manager</th><th>Risk</th><th>Onboarding stage</th><th>Products</th><th>Status</th><th>Last updated</th><th></th></tr></thead><tbody>@for(customer of filteredCustomers(); track customer.id){<tr (click)="selectCustomer(customer)"><td><input type="checkbox" (click)="$event.stopPropagation()"></td><td><div class="company"><span>{{customer.name.slice(0,1)}}</span><b>{{customer.name}}</b></div></td><td class="mono">{{customer.id}}</td><td>{{customer.industry}}</td><td>{{customer.manager}}</td><td><span class="badge" [class.high]="customer.risk==='High'" [class.low]="customer.risk==='Low'">{{customer.risk}}</span></td><td><span class="stage">{{customer.stage}}</span></td><td>{{customer.products}}</td><td><span class="status" [class.pending]="customer.status!=='Active'">{{customer.status}}</span></td><td>{{customer.updated}}</td><td><button class="icon-button" (click)="$event.stopPropagation(); showInfo('Open the customer row to review relationship details.')" aria-label="Customer actions"><span class="material-icons-round">more_horiz</span></button></td></tr>}</tbody></table></div><div class="pagination"><span>Showing {{filteredCustomers().length}} customers</span><div><button class="icon-button" (click)="showInfo('You are already on the first page.')"><span class="material-icons-round">chevron_left</span></button><b>1</b><button class="icon-button" (click)="showInfo('All available demo customers are shown.')"><span class="material-icons-round">chevron_right</span></button></div></div></section></ng-template>

    <ng-template #customer360><section class="customer-head"><button class="back" (click)="go('customers')"><span class="material-icons-round">arrow_back</span> Customers</button><div class="customer-title"><div class="company big"><span>A</span></div><div><p class="eyebrow">CUST-001248 · COMMERCIAL BANKING</p><h1>ACME Corporation <span class="status">Active</span></h1><p class="muted">Relationship manager: <b>Sarah Mitchell</b> <span class="divider"></span> Risk: <span class="badge">Medium</span></p></div><span class="push"></span>@if (canOnboard()) { <button class="secondary">Edit customer</button> } @if (canManageEntitlements()) { <button class="primary" (click)="drawer.set('request');requestStep.set(1)"><span class="material-icons-round">key</span> Request entitlement</button> } @if (!isReadOnly()) { <button class="icon-button"><span class="material-icons-round">more_horiz</span></button> }</div><nav class="tabs"><button class="active">Overview</button>@if (canOnboard()) { <button>Onboarding</button> } @if (canManageEntitlements()) { <button (click)="go('entitlements')">Products & entitlements</button> } @if (canApprove()) { <button (click)="go('approvals')">Approvals</button> } <button (click)="go('audit')">Audit history</button></nav></section><section class="customer-grid"><div class="customer-main"><article class="card progress-card"><div class="section-heading"><div><h2>Onboarding progress</h2><p>Case ONB-03289 · Started Aug 4, 2026</p></div><b class="progress-number">78%</b></div><div class="progress-track"><i></i></div><div class="progress-steps"><span class="complete"><i class="material-icons-round">check</i>Customer details</span><span class="complete"><i class="material-icons-round">check</i>KYC</span><span class="complete"><i class="material-icons-round">check</i>Due diligence</span><span class="complete"><i class="material-icons-round">check</i>Product setup</span><span class="current"><i></i>Entitlements</span><span><i></i>Final approval</span></div></article><section class="detail-cards"><article class="card"><div class="section-heading"><h2>Company information</h2>@if (canOnboard()) { <button class="icon-button"><span class="material-icons-round">edit</span></button> }</div><dl><dt>Legal name</dt><dd>ACME Corporation</dd><dt>Tax ID</dt><dd>••-•••4821</dd><dt>Entity type</dt><dd>C Corporation</dd><dt>Headquarters</dt><dd>Chicago, Illinois, US</dd></dl></article><article class="card"><div class="section-heading"><h2>Risk & compliance</h2><button class="icon-button"><span class="material-icons-round">open_in_new</span></button></div><dl><dt>Risk rating</dt><dd><span class="badge">Medium</span></dd><dt>KYC review</dt><dd><span class="status">Complete</span> · Aug 16, 2026</dd><dt>Screening</dt><dd><span class="status">Clear</span></dd><dt>Next review</dt><dd>Aug 16, 2027</dd></dl></article></section></div><aside class="customer-side"><article class="card"><div class="section-heading"><h2>Primary contacts</h2><button class="text-button">View all</button></div><div class="contact"><div class="avatar">JM</div><span><b>Jordan Matthews</b><small>Chief Financial Officer</small></span><button class="icon-button"><span class="material-icons-round">mail_outline</span></button></div><div class="contact"><div class="avatar gray">TS</div><span><b>Taylor Singh</b><small>Treasury Operations</small></span><button class="icon-button"><span class="material-icons-round">mail_outline</span></button></div></article><article class="card"><div class="section-heading"><h2>Recent activity</h2><button class="text-button" (click)="go('audit')">View audit</button></div><div class="mini-timeline"><p><i></i><span><b>Entitlement request created</b><small>Today, 10:18 AM · Alex Morgan</small></span></p><p><i></i><span><b>KYC review completed</b><small>Aug 16, 2026 · Compliance</small></span></p><p><i></i><span><b>Product setup completed</b><small>Aug 15, 2026 · Operations</small></span></p></div></article></aside></section></ng-template>

    <ng-template #entitlementPage><section class="page-header"><div><p class="eyebrow">CUSTOMER CONFIGURATION</p><h1>Products & entitlements</h1><p class="muted">ACME Corporation · CUST-001248</p></div><button class="primary" (click)="drawer.set('request');requestStep.set(1)"><span class="material-icons-round">add</span> Request entitlement</button></section><section class="product-grid">@for(product of products; track product.name){<article class="card product" [class.selected]="selectedProduct()===product.name" (click)="selectedProduct.set(product.name)"><div><span class="product-icon material-icons-round">{{product.icon}}</span><span class="badge" [class.high]="product.risk==='High'">{{product.risk}} risk</span></div><h3>{{product.name}}</h3><p><b>{{product.permissions}}</b> enabled permissions</p><div><span class="status">{{product.status}}</span><span class="material-icons-round arrow">arrow_forward</span></div></article>}</section><section class="card matrix"><div class="section-heading"><div><h2>Wire Transfers permission matrix</h2><p>Permissions are effective after final approval.</p></div><span class="badge high">HIGH-RISK PRODUCT</span></div><table><thead><tr><th>Capability</th><th>View</th><th>Create</th><th>Approve</th><th>Release</th><th>Admin</th></tr></thead><tbody>@for(row of permissions; track row.name){<tr><td><b>{{row.name}}</b>@if(row.warn){<small class="warning"><span class="material-icons-round">warning_amber</span> Dual approval required</small>}</td><td><span class="permission check">check</span></td><td><span class="permission" [class.check]="row.create">{{row.create?'check':'—'}}</span></td><td><span class="permission">—</span></td><td><span class="permission" [class.pending-permission]="row.release">{{row.release?'Pending':'—'}}</span></td><td><span class="permission">—</span></td></tr>}</tbody></table><p class="matrix-legend"><span class="permission check">check</span> Explicit permission <span class="permission inherited">check</span> Inherited <span class="permission pending-permission">Pending</span> Awaiting approval</p></section></ng-template>

    <ng-template #approvalPage><section class="page-header"><div><p class="eyebrow">MAKER / CHECKER CONTROLS</p><h1>Approval Center</h1><p class="muted">Review and authorize customer and entitlement changes.</p></div><span class="approval-summary"><b>{{approvals().length}}</b> requests require action</span></section><section class="card table-card"><div class="filters"><button class="active">All <b>{{approvals().length}}</b></button><button>High priority</button><button>Entitlements</button><button>Customer changes</button><button>KYC</button><button>My queue</button></div><div class="table-wrap"><table><thead><tr><th>Request ID</th><th>Customer</th><th>Change type</th><th>Requested by</th><th>Risk</th><th>Submitted</th><th>SLA</th><th>Status</th><th></th></tr></thead><tbody>@for(item of approvals(); track item.id){<tr (click)="selectApproval(item)"><td class="mono">{{item.id}}</td><td><b>{{item.customer}}</b></td><td>{{item.change}}</td><td>{{item.requestedBy}}</td><td><span class="badge" [class.critical]="item.risk==='critical'" [class.high]="item.risk==='high'">{{item.risk}}</span></td><td>{{item.submitted}}</td><td [class.high-text]="item.sla.includes('1h')">{{item.sla}}</td><td><span class="status pending">{{item.status}}</span></td><td><span class="material-icons-round">chevron_right</span></td></tr>}</tbody></table></div></section></ng-template>

    <ng-template #auditPage><section class="page-header"><div><p class="eyebrow">IMMUTABLE RECORD</p><h1>Audit history</h1><p class="muted">All activity is timestamped, immutable, and traceable.</p></div><button class="secondary"><span class="material-icons-round">filter_list</span> Filter events</button></section><section class="audit-layout"><article class="card audit-timeline"><div class="audit-day">RECENT ACTIVITY</div>@for(item of audit(); track item.title){<div class="audit-event"><div class="audit-time">{{item.time}}</div><div class="audit-line"><i [class]="item.type"></i></div><div><p class="audit-type">{{item.type}}</p><h3>{{item.title}}</h3><p>{{item.actor}} <span>·</span> {{item.detail}}</p><div class="audit-tags"><span>{{item.request}}</span><span class="mono">{{item.correlation}}</span><button>Technical details <span class="material-icons-round">expand_more</span></button></div></div></div>}</article><aside class="card audit-filter"><h3>Event types</h3><label class="check"><input type="checkbox" checked> All events</label><label class="check"><input type="checkbox" checked> Customer</label><label class="check"><input type="checkbox" checked> Entitlement</label><label class="check"><input type="checkbox"> Approval</label><label class="check"><input type="checkbox"> Security</label><label class="check"><input type="checkbox"> Failures</label><hr><h3>Correlation ID</h3><input placeholder="Search correlation ID"></aside></section></ng-template>

    <ng-template #eventPage><section class="page-header"><div><p class="eyebrow">KAFKA OPERATIONS</p><h1>Event Monitor</h1><p class="muted">Real-time visibility into domain event processing.</p></div><button class="secondary" (click)="loadEvents()"><span class="material-icons-round">refresh</span> Refresh</button></section><section class="metrics event-metrics"><article><small>Processed</small><strong>{{events().length}}</strong><p class="positive">Live event ledger</p></article><article><small>Pending</small><strong>0</strong><p>Consumer status available in health</p></article><article><small>Failed</small><strong class="high-text">0</strong><p class="high-text">Failures are persisted for review</p></article><article><small>Duplicates ignored</small><strong>0</strong><p>Idempotency protected</p></article></section><section class="card table-card"><div class="table-tools"><span class="select">All topics <span class="material-icons-round">expand_more</span></span><span class="select">All statuses <span class="material-icons-round">expand_more</span></span><span class="push"></span><span class="live"><i></i> Live updates</span></div><div class="table-wrap"><table><thead><tr><th>Event ID</th><th>Event type</th><th>Customer</th><th>Topic</th><th>Partition</th><th>Offset</th><th>Status</th><th>Retries</th><th>Timestamp</th><th>Correlation ID</th></tr></thead><tbody>@for(event of events(); track event.id){<tr (click)="selectedEvent.set(event)"><td class="mono">{{event.id}}</td><td><b>{{event.type}}</b></td><td>{{event.customer}}</td><td class="mono">{{event.topic}}</td><td>{{event.partition}}</td><td>{{event.offset}}</td><td><span class="event-status" [class]="event.status.toLowerCase()">{{event.status}}</span></td><td>{{event.retries}}</td><td>{{event.timestamp}}</td><td class="mono">{{event.correlation}}</td></tr>}</tbody></table></div></section>@if(selectedEvent()){<section class="event-detail card"><div><p class="eyebrow">EVENT DETAIL</p><h2>{{selectedEvent()!.id}} <span class="event-status" [class]="selectedEvent()!.status.toLowerCase()">{{selectedEvent()!.status}}</span></h2><p class="muted">{{selectedEvent()!.type}} · {{selectedEvent()!.topic}} · Correlation {{selectedEvent()!.correlation}}</p></div>@if(selectedEvent()!.status==='FAILED'){<button class="primary" (click)="retryEvent()"><span class="material-icons-round">replay</span> Retry event</button>}@else if(selectedEvent()!.status==='DUPLICATE'){<p class="info-note"><span class="material-icons-round">content_copy</span> Duplicate ignored - event already processed.</p>}</section>}</ng-template>

    <ng-template #healthPage><section class="page-header"><div><p class="eyebrow">OBSERVABILITY</p><h1>System health</h1><p class="muted">Platform availability and workload indicators.</p></div><span class="live"><i></i> Live status</span></section><section class="health-grid">@for(system of systems; track system.name){<article class="card system"><div><span class="system-icon material-icons-round">{{system.icon}}</span><span><h3>{{system.name}}</h3><p>Operational</p></span></div><span class="healthy"><i></i> Healthy</span><small>{{system.detail}}</small></article>}</section><section class="grid lower-grid"><article class="card activity"><div class="section-heading"><div><h2>API latency</h2><p>p95 response time, last hour</p></div><b class="metric-inline">142<span>ms</span></b></div><div class="bar-chart">@for(value of [41,63,48,71,52,60,36,45,55,38,63,44]; track $index){<i [style.height.%]="value"></i>}</div><div class="chart-labels"><span>10:00</span><span>10:15</span><span>10:30</span><span>10:45</span><span>11:00</span></div></article><article class="card health-stats"><h2>Workload</h2><p><span>Requests / min</span><b>1,842</b></p><p><span>Kafka consumer lag</span><b>18 <small>messages</small></b></p><p><span>Error rate</span><b class="positive">0.04%</b></p><p><span>Active connections</span><b>348</b></p></article></section></ng-template>
  `,
  styleUrl: './app.component.scss'
})
export class AppComponent {
  private readonly apiBaseUrl = this.publicSafeApiUrl((window as Window & { NEXORA_API_URL?: string }).NEXORA_API_URL || environment.apiBaseUrl);
  private readonly demoMode = !this.apiBaseUrl;
  private readonly demoUsers: DemoUser[] = [
    { email: 'alex.morgan@nexora.demo', password: 'Demo@12345', displayName: 'Alex Morgan', role: 'RELATIONSHIP_MANAGER' },
    { email: 'sam.taylor@nexora.demo', password: 'Demo@12345', displayName: 'Sam Taylor', role: 'OPERATIONS_MAKER' },
    { email: 'jordan.lee@nexora.demo', password: 'Demo@12345', displayName: 'Jordan Lee', role: 'APPROVER' },
    { email: 'admin@nexora.demo', password: 'Demo@12345', displayName: 'Nexora Admin', role: 'ADMIN' },
    { email: 'audit@nexora.demo', password: 'Demo@12345', displayName: 'Audit Viewer', role: 'AUDITOR' }
  ];
  private readonly demoCustomerRecords: Customer[] = demoCustomers.map(customer => ({ ...customer, backendId: customer.id }));
  private readonly demoApprovalRecords = [...demoApprovals];
  private readonly demoEventRecords = [...demoEvents];
  private readonly demoAuditRecords = [
    { time: 'Today, 10:18 AM', type: 'requested', title: 'ENTITLEMENT REQUESTED', actor: 'Alex Morgan - RELATIONSHIP_MANAGER', detail: 'ENTITLEMENT_REQUEST REQ-49218', request: 'ENTITLEMENT_REQUEST', correlation: 'CORR-849201' },
    { time: 'Today, 09:54 AM', type: 'published', title: 'CUSTOMER UPDATED', actor: 'System - EVENT_CONSUMER', detail: 'CUSTOMER CUST-001074', request: 'CUSTOMER', correlation: 'CORR-849177' },
    { time: 'Yesterday', type: 'approved', title: 'CUSTOMER APPROVED', actor: 'Jordan Lee - APPROVER', detail: 'CUSTOMER CUST-001102', request: 'CUSTOMER', correlation: 'CORR-849102' }
  ];
  constructor(private readonly http: HttpClient) {}
  signedIn = signal(false); collapsed = signal(false); page = signal<Page>('dashboard'); drawer = signal(''); requestStep = signal(1); toast = signal(''); filterStage = signal(''); selectedProduct = signal('Wire Transfers'); selectedEvent = signal<EventRecord | null>(null);
  email = 'alex.morgan@nexora.demo'; password = 'Demo@12345'; confirmPassword = ''; fullName = ''; customerSearch = ''; justification = ''; authError = '';
  isRegistering = signal(false); showPassword = signal(false); showConfirmPassword = signal(false); authPending = signal(false);
  role = signal<Role>('RELATIONSHIP_MANAGER');
  currentUser = signal({ displayName: 'Alex Morgan', email: 'alex.morgan@nexora.demo', role: 'RELATIONSHIP_MANAGER' as Role });
  customers = signal<Customer[]>([]); approvals = signal<any[]>([]); events = signal<EventRecord[]>([]); audit = signal<any[]>([]);
  selectedCustomer = signal<Customer | null>(null); selectedApproval = signal<any | null>(null);
  pipeline = [{label:'Submitted',count:5},{label:'KYC Review',count:7},{label:'Due Diligence',count:4},{label:'Product Setup',count:6},{label:'Entitlements',count:9},{label:'Approval',count:4},{label:'Activated',count:2}];
  attention = [{name:'ACME Corporation',detail:'Approval pending for 3 days',severity:'high',icon:'schedule'},{name:'Globex Industries',detail:'KYC document expiring',severity:'medium',icon:'description'},{name:'ENT-49218',detail:'Entitlement event failed',severity:'critical',icon:'error_outline'},{name:'Initech',detail:'Missing authorized signer',severity:'medium',icon:'person_off'}];
  products = [{name:'ACH Payments',icon:'account_balance',status:'Active',permissions:8,risk:'Medium'},{name:'Wire Transfers',icon:'currency_exchange',status:'Active',permissions:3,risk:'High'},{name:'Account Reporting',icon:'query_stats',status:'Active',permissions:4,risk:'Low'},{name:'Liquidity Management',icon:'water',status:'Pending',permissions:2,risk:'High'},{name:'Positive Pay',icon:'verified_user',status:'Active',permissions:5,risk:'Medium'},{name:'Trade Finance',icon:'public',status:'Not configured',permissions:0,risk:'High'}];
  permissions = [{name:'Payments',create:true,release:false,warn:false},{name:'ACH',create:true,release:false,warn:false},{name:'Wire transfer',create:true,release:true,warn:true},{name:'Reports',create:false,release:false,warn:false}];
  systems = [{name:'API Service',icon:'api',detail:'99.99% availability · 142ms p95'},{name:'PostgreSQL',icon:'storage',detail:'Connection pool 34% · 2ms query p95'},{name:'Kafka',icon:'hub',detail:'18 messages lag · 0 failed brokers'},{name:'Entitlement Consumer',icon:'sync_alt',detail:'12,482 events today · 27 duplicates'},{name:'Approval Service',icon:'task_alt',detail:'8 open requests · SLA 99.8%'}];
  filteredCustomers = computed(() => this.customers().filter(c => (c.name + c.id).toLowerCase().includes(this.customerSearch.toLowerCase())));
  pageTitle = computed(() => ({dashboard:'Dashboard',customers:'Customers',customer:'Customer 360',entitlements:'Entitlements',approvals:'Approvals',audit:'Audit History',events:'Event Monitor',health:'System Health'})[this.page()]);
  roleLabel = computed(() => ({RELATIONSHIP_MANAGER:'Relationship Manager',OPERATIONS_MAKER:'Operations Maker',APPROVER:'Approver',ADMIN:'Administrator',AUDITOR:'Auditor · Read only'})[this.role()]);
  canOnboard = computed(() => ['RELATIONSHIP_MANAGER', 'ADMIN'].includes(this.role()));
  canManageEntitlements = computed(() => ['OPERATIONS_MAKER', 'ADMIN'].includes(this.role()));
  canApprove = computed(() => ['APPROVER','ADMIN'].includes(this.role())); isAdmin = computed(() => this.role()==='ADMIN'); isReadOnly = computed(() => this.role()==='AUDITOR');
  login() {
    this.authError = ''; this.authPending.set(true);
    if (this.demoMode) { this.demoLogin(); return; }
    this.http.post<AuthResponse>(`${this.apiBaseUrl}/auth/login`, { email: this.email, password: this.password }).subscribe({ next: session => this.startSession(session), error: error => this.finishAuthError(error) });
  }
  passwordRules() { return { length: this.password.length >= 12, upper: /[A-Z]/.test(this.password) && /[a-z]/.test(this.password), number: /\d/.test(this.password) && /[^A-Za-z0-9]/.test(this.password) }; }
  passwordsMatch() { return this.password === this.confirmPassword; }
  canRegister() { const rules = this.passwordRules(); return !!this.fullName.trim() && !!this.email.trim() && rules.length && rules.upper && rules.number && this.passwordsMatch(); }
  switchAccessMode() { this.isRegistering.update(value => !value); this.confirmPassword = ''; this.authError = ''; this.showPassword.set(false); this.showConfirmPassword.set(false); }
  register() { if (!this.canRegister()) return; this.authError = ''; this.authPending.set(true); if (this.demoMode) { this.demoRegister(); return; } this.http.post<AuthResponse>(`${this.apiBaseUrl}/auth/register`, { displayName: this.fullName, email: this.email, password: this.password, confirmPassword: this.confirmPassword }).subscribe({ next: session => { this.startSession(session); this.toast.set('Secure account created. Welcome to Nexora.'); }, error: error => this.finishAuthError(error) }); }
  signOut() { this.signedIn.set(false); localStorage.removeItem('nexora.access-token'); this.password = ''; this.confirmPassword = ''; this.authError = ''; }
  private startSession(session: AuthResponse) { localStorage.setItem('nexora.access-token', session.accessToken); const user = { displayName: session.displayName, email: this.email.trim().toLowerCase(), role: session.role }; this.currentUser.set(user); this.role.set(session.role); this.authPending.set(false); this.signedIn.set(true); this.loadCustomers(); this.loadAudit(); if (this.canManageEntitlements() || this.canApprove()) this.loadApprovals(); if (this.isAdmin()) this.loadEvents(); }
  private finishAuthError(error: { error?: { message?: string } }) { this.authPending.set(false); this.authError = error.error?.message || 'Unable to securely process this request. Try again.'; }
  firstName() { return this.currentUser().displayName.split(' ')[0]; }
  initials() { return this.currentUser().displayName.split(' ').map(part => part[0]).join('').slice(0, 2).toUpperCase(); }
  showInfo(message: string) { this.toast.set(message); }
  openSearch() { this.go('customers'); this.toast.set('Use the customer search field to find a relationship or customer ID.'); }
  filterPipeline(stage: string) { this.filterStage.set(stage); this.go('customers'); this.toast.set(`Showing customer relationships in the ${stage} onboarding stage.`); }
  createCustomer() {
    const legalName = window.prompt('Customer legal name');
    if (!legalName?.trim()) return;
    const customerNumber = window.prompt('Customer ID, for example CUST-001250');
    if (!customerNumber?.trim()) return;
    const industry = window.prompt('Industry');
    if (!industry?.trim()) return;
    if (this.demoMode) {
      const customer = { id: customerNumber.trim().toUpperCase(), backendId: customerNumber.trim().toUpperCase(), name: legalName.trim(), industry: industry.trim(), manager: this.currentUser().displayName, risk: 'Medium', stage: 'Submitted', products: 0, status: 'In review', updated: 'Just now' };
      this.demoCustomerRecords.unshift(customer);
      this.customers.set([...this.demoCustomerRecords]);
      this.selectedCustomer.set(customer);
      this.toast.set(`${customer.name} was created and added to onboarding.`);
      return;
    }
    this.http.post<CustomerResponse>(`${this.apiBaseUrl}/customers`, { legalName: legalName.trim(), customerNumber: customerNumber.trim().toUpperCase(), industry: industry.trim() }, { headers: this.authHeaders() }).subscribe({
      next: customer => { this.loadCustomers(); this.toast.set(`${customer.legalName} was created and added to onboarding.`); },
      error: error => this.toast.set(error.error?.message || 'Unable to create this customer. Use a unique CUST-000000 ID.')
    });
  }
  go(page: Page) { if ((page === 'entitlements' && !this.canManageEntitlements()) || (page === 'approvals' && !this.canApprove()) || ((page === 'events' || page === 'health') && !this.isAdmin())) { this.toast.set('Your role does not have access to this operational area.'); return; } this.page.set(page); this.drawer.set(''); if (page === 'approvals') this.loadApprovals(); if (page === 'audit') this.loadAudit(); if (page === 'events') this.loadEvents(); }
  selectCustomer(customer: Customer) { this.selectedCustomer.set(customer); this.go('customer'); }
  selectApproval(approval: any) { this.selectedApproval.set(approval); this.drawer.set('approval'); }
  advanceRequest() {
    if (this.requestStep() < 4) { this.requestStep.update(v => v + 1); return; }
    const customer = this.selectedCustomer() || this.customers()[0];
    if (!customer?.backendId) { this.toast.set('Select a customer before requesting an entitlement.'); return; }
    if (this.justification.trim().length < 20) { this.toast.set('Add a business justification of at least 20 characters.'); this.requestStep.set(3); return; }
    if (this.demoMode) { this.demoSubmitEntitlement(customer); return; }
    this.http.post<EntitlementResponse>(`${this.apiBaseUrl}/entitlement-requests`, { customerId: customer.backendId, product: this.selectedProduct(), permission: 'RELEASE', justification: this.justification.trim() }, { headers: this.authHeaders() }).subscribe({ next: () => { this.drawer.set(''); this.justification = ''; this.requestStep.set(1); this.toast.set('Entitlement request submitted for independent approval.'); this.loadApprovals(); }, error: error => this.toast.set(error.error?.message || 'Unable to submit the entitlement request.') });
  }
  approve() { this.decideApproval('approve'); }
  reject() { this.decideApproval('reject'); }
  retryEvent() { this.toast.set('Event retry initiated. Processing is underway.'); this.selectedEvent.set({...this.selectedEvent()!, status:'RETRYING'}); }
  private authHeaders() { return new HttpHeaders({ Authorization: `Bearer ${localStorage.getItem('nexora.access-token') || ''}` }); }
  loadCustomers() { if (this.demoMode) { this.customers.set([...this.demoCustomerRecords]); if (!this.selectedCustomer() && this.demoCustomerRecords.length) this.selectedCustomer.set(this.demoCustomerRecords[0]); return; } this.http.get<CustomerResponse[]>(`${this.apiBaseUrl}/customers`, { headers: this.authHeaders() }).subscribe({ next: records => { const mapped = records.map(record => this.mapCustomer(record)); this.customers.set(mapped); if (!this.selectedCustomer() && mapped.length) this.selectedCustomer.set(mapped[0]); }, error: () => this.toast.set('Unable to load customers from the API.') }); }
  loadApprovals() { if (this.demoMode) { this.approvals.set([...this.demoApprovalRecords]); return; } this.http.get<EntitlementResponse[]>(`${this.apiBaseUrl}/entitlement-requests`, { headers: this.authHeaders() }).subscribe({ next: records => this.approvals.set(records.filter(record => record.status === 'PENDING_APPROVAL').map(record => ({ id: record.id, customer: this.customerName(record.customerId), change: `${record.product} ${record.permission}`, requestedBy: record.requestedBy, risk: record.riskLevel.toLowerCase(), submitted: this.formatDate(record.requestedAt), sla: 'Within SLA', status: 'Awaiting review' }))), error: () => this.approvals.set([]) }); }
  loadAudit() { if (this.demoMode) { this.audit.set([...this.demoAuditRecords]); return; } this.http.get<AuditResponse[]>(`${this.apiBaseUrl}/audit-events`, { headers: this.authHeaders() }).subscribe({ next: records => this.audit.set(records.map(record => ({ time: this.formatDate(record.occurredAt), type: this.auditType(record.action), title: record.action.replaceAll('_', ' '), actor: `${record.actor} · ${record.actorRole}`, detail: `${record.entityType} ${record.entityId}`, request: record.entityType, correlation: record.correlationId }))), error: () => this.audit.set([]) }); }
  loadEvents() { if (this.demoMode) { this.events.set([...this.demoEventRecords]); return; } this.http.get<EventResponse[]>(`${this.apiBaseUrl}/events`, { headers: this.authHeaders() }).subscribe({ next: records => this.events.set(records.map(record => ({ id: record.eventId, type: record.eventType, customer: this.customerName(record.entityId), topic: 'entitlement-events', partition: 0, offset: 0, status: record.status, retries: 0, timestamp: this.formatDate(record.processedAt), correlation: record.correlationId }))), error: () => this.events.set([]) }); }
  private decideApproval(decision: 'approve' | 'reject') { const approval = this.selectedApproval(); if (!approval) return; if (this.demoMode) { const index = this.demoApprovalRecords.findIndex(item => item.id === approval.id); if (index >= 0) this.demoApprovalRecords.splice(index, 1); this.approvals.set([...this.demoApprovalRecords]); this.demoAuditRecords.unshift({ time: 'Just now', type: decision === 'approve' ? 'approved' : 'processed', title: `ENTITLEMENT ${decision.toUpperCase()}D`, actor: `${this.currentUser().displayName} - ${this.role()}`, detail: `ENTITLEMENT_REQUEST ${approval.id}`, request: 'ENTITLEMENT_REQUEST', correlation: `CORR-${Date.now()}` }); this.drawer.set(''); this.toast.set(`Request ${decision === 'approve' ? 'approved' : 'rejected'} successfully.`); return; } this.http.post<EntitlementResponse>(`${this.apiBaseUrl}/entitlement-requests/${approval.id}/${decision}`, { comment: `${decision === 'approve' ? 'Approved' : 'Rejected'} through the controlled maker-checker workflow.` }, { headers: this.authHeaders() }).subscribe({ next: () => { this.drawer.set(''); this.toast.set(`Request ${decision === 'approve' ? 'approved' : 'rejected'} successfully.`); this.loadApprovals(); this.loadAudit(); if (this.isAdmin()) this.loadEvents(); }, error: error => this.toast.set(error.error?.message || 'This decision could not be completed.') }); }
  private demoLogin() { const account = this.demoUsers.find(user => user.email === this.email.trim().toLowerCase()); if (!account || account.password !== this.password) { this.finishAuthError({ error: { message: 'Use a demo account such as alex.morgan@nexora.demo with password Demo@12345.' } }); return; } this.startSession({ accessToken: `demo-token-${account.role}`, tokenType: 'Bearer', role: account.role, displayName: account.displayName }); this.toast.set('Demo workspace loaded without requesting local-device access.'); }
  private demoRegister() { if (this.demoUsers.some(user => user.email === this.email.trim().toLowerCase())) { this.finishAuthError({ error: { message: 'This email already exists. Sign in with the existing account.' } }); return; } const account = { email: this.email.trim().toLowerCase(), password: this.password, displayName: this.fullName.trim(), role: 'AUDITOR' as Role }; this.demoUsers.push(account); this.startSession({ accessToken: 'demo-token-auditor', tokenType: 'Bearer', role: account.role, displayName: account.displayName }); this.toast.set('Secure account created with read-only auditor access.'); }
  private demoSubmitEntitlement(customer: Customer) { const request = { id: `REQ-${Date.now().toString().slice(-5)}`, customer: customer.name, change: `${this.selectedProduct()} RELEASE`, requestedBy: this.currentUser().displayName, risk: 'critical' as const, submitted: 'Just now', sla: 'Within SLA', status: 'Awaiting review' }; this.demoApprovalRecords.unshift(request); this.approvals.set([...this.demoApprovalRecords]); this.demoAuditRecords.unshift({ time: 'Just now', type: 'requested', title: 'ENTITLEMENT REQUESTED', actor: `${this.currentUser().displayName} - ${this.role()}`, detail: `ENTITLEMENT_REQUEST ${request.id}`, request: 'ENTITLEMENT_REQUEST', correlation: `CORR-${Date.now()}` }); this.drawer.set(''); this.justification = ''; this.requestStep.set(1); this.toast.set('Entitlement request submitted for independent approval.'); }
  private publicSafeApiUrl(value: string) { const apiUrl = value.trim(); const isPublicSite = !['localhost', '127.0.0.1', '0.0.0.0'].includes(window.location.hostname); const isLocalApiUrl = /^https?:\/\/(localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\])(?::|\/|$)/i.test(apiUrl); return isPublicSite && isLocalApiUrl ? '' : apiUrl; }
  private mapCustomer(record: CustomerResponse): Customer { return { id: record.customerNumber, backendId: record.id, name: record.legalName, industry: record.industry, manager: 'Relationship team', risk: record.riskLevel, stage: record.onboardingStage, products: 0, status: record.onboardingStage === 'Activated' ? 'Active' : 'In review', updated: this.formatDate(record.updatedAt) }; }
  private customerName(id: string) { return this.customers().find(customer => customer.backendId === id)?.name || id; }
  private formatDate(value: string) { return new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }); }
  private auditType(action: string) { return action.includes('APPROVED') ? 'approved' : action.includes('REQUEST') ? 'requested' : action.includes('ACTIVATED') ? 'processed' : 'published'; }
}
